-- Canonical Thai administrative boundaries used by the GIS base-data layer.
-- Source: district_boundary.geojson SHA256 571C264C51B1D02A38EA2B0759BC92AE2FCA1A4E385E3C9E1E89041258A118D7
-- Source: subdistrict_boundary.geojson SHA256 0BEBBFE9E30384FCAE884C61CA0803472F3EF78378CBDFCB4F41821F221B0451
-- Idempotent: preserve extra site rows and upsert this canonical set by code.

CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE IF NOT EXISTS public.district_boundary (
  id serial PRIMARY KEY,
  code varchar(20) NOT NULL UNIQUE,
  name_th varchar(120) NOT NULL,
  name_en varchar(120),
  province_code varchar(20),
  province_th varchar(120),
  geom geometry(MultiPolygon, 4326)
);

CREATE INDEX IF NOT EXISTS district_boundary_geom_idx
  ON public.district_boundary USING gist (geom);

ON CONFLICT (code) DO UPDATE SET
  name_th = EXCLUDED.name_th,
  name_en = EXCLUDED.name_en,
  province_code = EXCLUDED.province_code,
  province_th = EXCLUDED.province_th,
  geom = EXCLUDED.geom;

CREATE TABLE IF NOT EXISTS public.subdistrict_boundary (
  id serial PRIMARY KEY,
  code varchar(20) NOT NULL UNIQUE,
  name_th varchar(120) NOT NULL,
  name_en varchar(120),
  district_code varchar(20),
  district_th varchar(120),
  province_code varchar(20),
  province_th varchar(120),
  geom geometry(MultiPolygon, 4326)
);

CREATE INDEX IF NOT EXISTS subdistrict_boundary_district_code_idx
  ON public.subdistrict_boundary (district_code);
CREATE INDEX IF NOT EXISTS subdistrict_boundary_geom_idx
  ON public.subdistrict_boundary USING gist (geom);

ON CONFLICT (code) DO UPDATE SET
  name_th = EXCLUDED.name_th,
  name_en = EXCLUDED.name_en,
  district_code = EXCLUDED.district_code,
  district_th = EXCLUDED.district_th,
  province_code = EXCLUDED.province_code,
  province_th = EXCLUDED.province_th,
  geom = EXCLUDED.geom;

DO $$
BEGIN
  IF (SELECT COUNT(*) FROM public.district_boundary) < 9 THEN
    RAISE EXCEPTION 'Expected 9 district boundaries';
  END IF;
  IF (SELECT COUNT(*) FROM public.subdistrict_boundary) < 93 THEN
    RAISE EXCEPTION 'Expected 93 subdistrict boundaries';
  END IF;
  IF EXISTS (SELECT 1 FROM public.district_boundary WHERE geom IS NULL OR NOT ST_IsValid(geom)) THEN
    RAISE EXCEPTION 'Invalid district boundary geometry';
  END IF;
  IF EXISTS (SELECT 1 FROM public.subdistrict_boundary WHERE geom IS NULL OR NOT ST_IsValid(geom)) THEN
    RAISE EXCEPTION 'Invalid subdistrict boundary geometry';
  END IF;
END $$;
